import 'package:flutter/material.dart';
class AdminStatusChip extends StatelessWidget{const AdminStatusChip(this.status,{super.key});final String? status;@override Widget build(BuildContext context){final s=(status??'UNKNOWN').toUpperCase();final c=s=='ACTIVE'||s=='APPROVED'?Colors.green:s=='PENDING'?Colors.orange:Colors.red;return Chip(label:Text(s),side:BorderSide(color:c),labelStyle:TextStyle(color:c,fontWeight:FontWeight.w600));}}
class InfoRow extends StatelessWidget{const InfoRow(this.label,this.value,{super.key});final String label;final Object? value;@override Widget build(BuildContext context)=>Padding(padding:const EdgeInsets.symmetric(vertical:4),child:Row(crossAxisAlignment:CrossAxisAlignment.start,children:[SizedBox(width:130,child:Text(label,style:const TextStyle(fontWeight:FontWeight.w600))),Expanded(child:Text((value==null||value.toString().isEmpty)?'-':value.toString()))]));}
